/*
 * LoRa Weather Station - TRANSMITTER (Board 1)
 * ESP32 + SX1276/RFM95W + DHT22
 *
 * Reads temperature, humidity, and battery voltage.
 * Sends a JSON payload over LoRa every 30 seconds.
 * Designed for remote / battery-powered deployment.
 *
 * Libraries needed:
 *   - LoRa by Sandeep Mistry
 *   - DHT sensor library by Adafruit
 *   - ArduinoJson (for JSON serialization)
 */

#include <SPI.h>
#include <LoRa.h>
#include <DHT.h>
#include <ArduinoJson.h>

// --- Pin Definitions (ESP32 + LoRa SX1276) ---
#define LORA_SS     5
#define LORA_RST    14
#define LORA_DIO0   26
#define DHT_PIN     4
#define BATT_ADC    34    // Battery voltage divider -> ADC pin

// --- LoRa Parameters ---
#define LORA_FREQ      868E6   // 868 MHz (EU) - change to 915E6 for US
#define SF             10      // Spreading Factor (7-12). Higher = longer range, slower.
#define BW             125000  // Bandwidth in Hz
#define CR             5       // Coding Rate 4/5
#define TX_POWER       17      // dBm (max 20 for SX1276)
#define SYNC_WORD      0x12    // Sync word to filter own packets
#define TX_INTERVAL_MS 30000   // Send every 30 seconds

// --- DHT22 ---
#define DHT_TYPE DHT22
DHT dht(DHT_PIN, DHT_TYPE);

// --- Battery voltage divider ratio ---
// If using a 2:1 divider (R1=100k, R2=100k):
const float BATT_DIVIDER = 2.0;
const float ADC_VREF = 3.3;
const int ADC_RESOLUTION = 4095;

// --- Packet counter ---
unsigned long packetCount = 0;

// --- Deep-sleep duration (set to 0 to disable) ---
#define SLEEP_SECONDS 0   // Set >0 for deep-sleep between transmissions

void setup() {
  Serial.begin(115200);
  delay(1000);
  Serial.println();
  Serial.println("========================================");
  Serial.println("  LoRa Weather Station - Transmitter");
  Serial.println("========================================");

  // DHT22
  dht.begin();
  Serial.println("[INIT] DHT22 sensor ready.");

  // LoRa
  SPI.begin(18, 19, 23, LORA_SS);  // SCK, MISO, MOSI, SS
  LoRa.setPins(LORA_SS, LORA_RST, LORA_DIO0);

  if (!LoRa.begin(LORA_FREQ)) {
    Serial.println("[ERROR] LoRa init failed!");
    while (1) { delay(1000); }
  }

  // LoRa configuration
  LoRa.setSpreadingFactor(SF);
  LoRa.setSignalBandwidth(BW);
  LoRa.setCodingRate4(CR);
  LoRa.setTxPower(TX_POWER);
  LoRa.setSyncWord(SYNC_WORD);
  LoRa.enableCrc();
  LoRa.setPreambleLength(8);

  Serial.println("[INIT] LoRa radio configured.");
  Serial.print("  Frequency : "); Serial.print(LORA_FREQ / 1E6); Serial.println(" MHz");
  Serial.print("  SF        : "); Serial.println(SF);
  Serial.print("  Bandwidth : "); Serial.print(BW / 1000); Serial.println(" kHz");
  Serial.print("  TX Power  : "); Serial.print(TX_POWER); Serial.println(" dBm");
  Serial.println("---");
}

float readBatteryVoltage() {
  int raw = analogRead(BATT_ADC);
  float voltage = (raw / (float)ADC_RESOLUTION) * ADC_VREF * BATT_DIVIDER;
  return voltage;
}

void loop() {
  packetCount++;

  // Read sensors
  float temperature = dht.readTemperature();   // Celsius
  float humidity    = dht.readHumidity();
  float batteryV    = readBatteryVoltage();

  // Check DHT read errors
  bool dhtError = isnan(temperature) || isnan(humidity);

  // Build JSON payload
  StaticJsonDocument<128> doc;
  doc["id"]    = "ws-01";          // Station ID
  doc["pkt"]   = packetCount;
  doc["temp"]  = dhtError ? -999.0 : round(temperature * 10.0) / 10.0;
  doc["hum"]   = dhtError ? -1.0   : round(humidity * 10.0) / 10.0;
  doc["bat"]   = round(batteryV * 100.0) / 100.0;

  char payload[128];
  serializeJson(doc, payload, sizeof(payload));

  // Print to local serial
  Serial.print("[TX #"); Serial.print(packetCount); Serial.print("] ");
  Serial.println(payload);

  // Send over LoRa
  LoRa.beginPacket();
  LoRa.print(payload);
  LoRa.endPacket();

  Serial.println("  -> Packet sent!");
  Serial.println("---");

  // Deep-sleep mode (optional, uncomment below to enable)
  // #if SLEEP_SECONDS > 0
  //   LoRa.sleep();
  //   esp_sleep_enable_timer_wakeup(SLEEP_SECONDS * 1000000ULL);
  //   esp_deep_sleep_start();
  // #endif

  delay(TX_INTERVAL_MS);
}

