/*
 * LoRa Weather Station - RECEIVER (Board 2)
 * ESP32 + SX1276/RFM95W + SSD1306 OLED
 *
 * Receives JSON weather packets from the Transmitter.
 * Displays temperature, humidity, battery, and signal
 * quality (RSSI/SNR) on a 128x64 OLED display.
 * Also logs all data to Serial Monitor.
 *
 * Libraries needed:
 *   - LoRa by Sandeep Mistry
 *   - Adafruit SSD1306
 *   - Adafruit GFX Library
 *   - ArduinoJson (for JSON deserialization)
 */

#include <SPI.h>
#include <LoRa.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <ArduinoJson.h>

// --- Pin Definitions (ESP32 + LoRa SX1276) ---
#define LORA_SS     5
#define LORA_RST    14
#define LORA_DIO0   26

// --- OLED ---
#define SCREEN_WIDTH  128
#define SCREEN_HEIGHT 64
#define OLED_SDA      21
#define OLED_SCL      22
#define OLED_RST      -1   // -1 if not connected

// --- LoRa Parameters (must match Transmitter) ---
#define LORA_FREQ   868E6
#define SF          10
#define BW          125000
#define CR          5
#define SYNC_WORD   0x12

// --- Display ---
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RST);

// --- Packet tracking ---
unsigned long rxCount = 0;
unsigned long lastPacketTime = 0;
const long TIMEOUT_MS = 90000;  // 90s without a packet = stale

// --- Last known values ---
float lastTemp     = -999;
float lastHum      = -1;
float lastBat      = 0;
float lastRSSI     = 0;
float lastSNR      = 0;
String lastStationId = "--";

void drawHeader() {
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.print("LoRa Weather Station");
  display.drawLine(0, 10, 127, 10, SSD1306_WHITE);
}

void updateDisplay() {
  display.clearDisplay();
  drawHeader();

  display.setTextSize(1);

  // Station ID + packet count
  display.setCursor(0, 14);
  display.print("Station: ");
  display.print(lastStationId);
  display.print("  #");
  display.print(rxCount);

  // Temperature
  display.setCursor(0, 26);
  display.print("Temp : ");
  if (lastTemp > -900) {
    display.print(lastTemp, 1);
    display.print(" C");
  } else {
    display.print("ERR");
  }

  // Humidity
  display.setCursor(0, 36);
  display.print("Hum  : ");
  if (lastHum >= 0) {
    display.print(lastHum, 1);
    display.print(" %");
  } else {
    display.print("ERR");
  }

  // Battery
  display.setCursor(0, 46);
  display.print("Batt : ");
  display.print(lastBat, 2);
  display.print(" V");

  // Signal quality
  display.setCursor(0, 56);
  display.print("RSSI:");
  display.print((int)lastRSSI);
  display.print("  SNR:");
  display.print(lastSNR, 1);

  // Stale indicator
  if (millis() - lastPacketTime > TIMEOUT_MS && lastPacketTime > 0) {
    display.setTextSize(1);
    display.setCursor(100, 14);
    display.print("STALE");
  }

  display.display();
}

void setup() {
  Serial.begin(115200);
  delay(1000);
  Serial.println();
  Serial.println("========================================");
  Serial.println("  LoRa Weather Station - Receiver");
  Serial.println("========================================");

  // OLED reset
  if (OLED_RST > 0) {
    pinMode(OLED_RST, OUTPUT);
    digitalWrite(OLED_RST, LOW);
    delay(20);
    digitalWrite(OLED_RST, HIGH);
  }

  Wire.begin(OLED_SDA, OLED_SCL);
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("[ERROR] OLED init failed!");
    while (1) { delay(1000); }
  }
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println("Waiting for LoRa...");
  display.display();
  Serial.println("[INIT] OLED display ready.");

  // LoRa
  SPI.begin(18, 19, 23, LORA_SS);
  LoRa.setPins(LORA_SS, LORA_RST, LORA_DIO0);

  if (!LoRa.begin(LORA_FREQ)) {
    Serial.println("[ERROR] LoRa init failed!");
    while (1) { delay(1000); }
  }

  LoRa.setSpreadingFactor(SF);
  LoRa.setSignalBandwidth(BW);
  LoRa.setCodingRate4(CR);
  LoRa.setSyncWord(SYNC_WORD);
  LoRa.enableCrc();

  Serial.println("[INIT] LoRa radio configured.");
  Serial.print("  Listening on "); Serial.print(LORA_FREQ / 1E6); Serial.println(" MHz");
  Serial.println("---");
}

void loop() {
  int packetSize = LoRa.parsePacket();

  if (packetSize) {
    rxCount++;
    lastPacketTime = millis();

    // Read the raw payload
    char buffer[128];
    int idx = 0;
    while (LoRa.available() && idx < (int)sizeof(buffer) - 1) {
      buffer[idx++] = (char)LoRa.read();
    }
    buffer[idx] = 0;

    // Signal quality
    lastRSSI = LoRa.packetRssi();
    lastSNR  = LoRa.packetSnr();

    // Parse JSON
    StaticJsonDocument<128> doc;
    DeserializationError err = deserializeJson(doc, buffer);

    if (!err) {
      lastStationId = doc["id"].as<String>();
      lastTemp      = doc["temp"].as<float>();
      lastHum       = doc["hum"].as<float>();
      lastBat       = doc["bat"].as<float>();

      // Serial log
      Serial.print("[RX #"); Serial.print(rxCount); Serial.print("] ");
      Serial.print("Station:"); Serial.print(lastStationId);
      Serial.print(" Temp:"); Serial.print(lastTemp, 1);
      Serial.print("C  Hum:"); Serial.print(lastHum, 1);
      Serial.print("%  Bat:"); Serial.print(lastBat, 2);
      Serial.print("V  RSSI:"); Serial.print((int)lastRSSI);
      Serial.print("dBm  SNR:"); Serial.print(lastSNR, 1);
      Serial.println("dB");
    } else {
      Serial.print("[RX] JSON parse error: ");
      Serial.println(err.c_str());
      Serial.print("  Raw: ");
      Serial.println(buffer);
    }

    Serial.println("---");
    updateDisplay();
  }
}
